import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a vector-sum game, a player chooses a set $S$ of vectors $(x,y)$ where $x$ and $y$ are integers from $1$ to ${N}$. A chosen set $S$ is valid if for any two disjoint, non-empty subsets of $S$, the sum of the vectors in one subset never equals the sum of the vectors in the other. The score of a valid set is the sum of all the $x$ and $y$ coordinates of its vectors, i.e., $\\sum_{(x,y) \\in S} (x+y)$. What is the highest possible score a player can achieve?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# N=2,3,4 are reasonable for contest settings. N=5 is computationally heavy.
N = rng.randint(2, 4)
return {'N': N}

    def verifier(assign):
N = assign['N']

if not isinstance(N, int) or not (2 <= N <= 4):
    # N=2: |S|=3, |D|<=27. Fast.
    # N=3: |S|=5, |D|<=243. Fast.
    # N=4: |S|=7, |D|<=2187. Manageable.
    # N=5: |S|=9, |D|<=19683. Slows down significantly.
    # N=6: |S|=13, |D| is huge. Too slow.
    return False, None

candidates = []
for x in range(1, N + 1):
    for y in range(1, N + 1):
        candidates.append((x, y))

# Sort candidates by x+y descending, then x descending as a tie-breaker.
# This is the crucial step of the greedy algorithm.
candidates.sort(key=lambda p: (p[0] + p[1], p[0]), reverse=True)

S = []
# D is the set of vectors that can be formed by sum/difference of vectors in S
D = {(0, 0)}

for v_k in candidates:
    # A new vector v_k creates a conflict if v_k = sum(c_i * v_i) for v_i in S.
    # This is equivalent to v_k being in the set D of existing combinations.
    if v_k not in D:
        S.append(v_k)
        # Update D with all new combinations involving v_k.
        new_combinations = set()
        for d in D:
            new_combinations.add((d[0] + v_k[0], d[1] + v_k[1]))
            new_combinations.add((d[0] - v_k[0], d[1] - v_k[1]))
        D.update(new_combinations)

total_sum = sum(p[0] + p[1] for p in S)
return True, total_sum


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

